          'err.headless.schema_upgrade': '이 빌드가 읽는 로컬 데이터베이스보다 현재 데이터베이스 버전이 오래되어 읽기 전용 연결로 업그레이드할 수 없습니다. 데스크톱 앱을 한 번 실행하거나 헤드리스 환경에서 zeppbridge-cli reprocess를 실행하세요. 어느 방법이든 업그레이드 전에 백업합니다.',
          'err.headless.program_outdated': '데이터베이스를 읽는 CLI / MCP가 데스크톱 앱보다 오래되어 이 데이터베이스 버전을 읽을 수 없습니다. AI 도구가 이전 사본을 가리키는 경우가 많습니다. 설정에서 해당 도구를 다시 연결하세요(Claude Desktop은 ZeppBridge.mcpb를 다시 생성해 설치). 이전 확장 프로그램이나 오래된 설치 폴더를 가리키는 항목을 제거한 뒤 AI 도구를 다시 시작하세요.',
