    'lib/metricInfo/training': {
          vo2maxWhat: '최대 산소 섭취량(VO₂max): 체중 1kg당 1분 동안 사용할 수 있는 산소량(ml/kg/min)입니다.',
          vo2maxChart: '야외 달리기 후에만 갱신되며 1년에 몇 번 되지 않습니다. 한두 번의 값보다 장기 추세가 유용하며, 추세를 보려면 6개월 범위를 선택하세요.',
          vo2maxHow: '시계가 야외 달리기 후 추정하며 고급 데이터로 동기화됩니다. 공식 API는 VO₂max를 제공하지 않습니다.',
          training_loadWhat: '훈련 부하: Zepp가 보고하는 이동 7일 훈련 부하이며 단위가 없습니다.',
          training_loadChart: '하루에 점 하나를 표시합니다. 최신 값 옆의 수준(낮음 / 보통 / 높음 / 매우 높음)은 600 참고 척도로 나눈 대략적인 안내이며 시계가 매긴 등급은 아닙니다.',
          training_loadHow: '시계가 매일 제공하며 고급 데이터로 동기화됩니다. 공식 API는 일별 훈련 부하를 제공하지 않습니다. 수준은 ZeppBridge가 참고 척도로 계산합니다.',
          pai_totalWhat: 'PAI 활력 지수: 최근 7일 동안의 개인 활동 점수입니다.',
          pai_totalChart: '하루에 점 하나를 표시하며 해당 날짜까지의 이동 7일 합계입니다. 그날 새로 얻은 점수를 표시하는 것은 아닙니다.',
          pai_totalHow: '공식 인증과 고급 데이터 모두 PAI를 제공하며 Zepp 기준에 따라 7일 동안 누적합니다.',
          lactate_thresholdWhat: '젖산 역치: 강도가 더 높아지면 피로가 빠르게 쌓이기 시작하는 지점으로 심박수와 페이스로 나타냅니다.',
          lactate_thresholdChart: '심박수와 페이스 두 선을 표시합니다(페이스 축은 빠를수록 위에 오도록 반전). 일정 시간 고강도 달리기를 한 뒤에만 갱신됩니다.',
          lactate_thresholdHow: '시계가 고강도 달리기 후 추정하며 고급 데이터로 동기화됩니다. 공식 API는 젖산 역치를 제공하지 않습니다.',
          training_balanceWhat: '운동 부하 균형: 최근 7일 부하를 최근 28일 주간 평균과 비교한 급성 대 만성 부하 비율입니다.',
          training_balanceChart: '7일 부하, 28일 주간 평균, 급성 대 만성 비율을 표시합니다. 선이 끊긴 곳은 계산하지 않은 불완전한 기간이며 0을 뜻하지 않습니다.',
          training_balanceHow: 'ZeppBridge에서 계산합니다. 각 운동의 부하를 운동 시작일의 현지 날짜 기준으로 합산합니다(Zepp의 이동 7일 부하를 사용하면 같은 운동을 중복 계산합니다). 급성 대 만성 비율 = 7일 합계 ÷ (28일 합계 ÷ 4)입니다. 고급 데이터로 운동 목록 전체를 동기화했고 모든 운동에 유효한 부하가 있는 날만 완전한 것으로 처리합니다. 운동이 없음을 확인한 날만 0으로 계산하며, 7일 또는 28일 기간이 불완전하면 비워 둡니다. 공식 API에서 가져온 운동에는 부하가 없으므로 공식 동기화만 받은 날은 계산에 포함하지 않습니다.',
        },
