          'ui.ai_template.week_review.name': '이번 주 돌아보기',
          'ui.ai_template.week_review.prompt': '이번 주를 살펴봐 주세요. 수면, 회복, 심박수, 활동량이 평소와 어떻게 달라졌는지, 주의할 변화와 일반적인 변동은 무엇인지 확인해 주세요. 데이터만 근거로 판단하고 진단은 하지 말며, 데이터가 없는 날짜는 그대로 알려 주세요.',
