    'lib/aiTask/markdownGuide': {
          'guide': '읽는 방법:\n- 표는 모두 CSV 코드 블록입니다. 첫 줄은 열 이름이며 괄호 안은 단위입니다.\n- 셀이 비어 있으면 해당 날짜 또는 시점에 데이터가 없는 것이며 0을 뜻하지 않습니다. 값을 채우거나 추측하지 마세요.\n- Daily metrics는 하루에 한 행, Sleep은 한 밤에 한 행, Workouts는 운동 한 번에 한 행입니다. Coverage에는 각 데이터 종류의 날짜 범위와 실제 데이터가 있는 날짜 수가 표시됩니다.\n- 운동 곡선(Samples)은 Summary의 curve_average_seconds 값에 따라 초 단위로 평균을 냅니다. heart_rate_min / heart_rate_max는 각 구간의 최저 및 최고 심박수입니다. 전체 운동 통계는 초 단위 전체 데이터를 사용해 계산되며 Curve statistics에 있습니다.\n- workouts_summary_only에 포함된 운동은 파일을 읽기 쉽게 요약 행만 남겼습니다.'
        },
